def maxValueAt(n, index, maxSum):
    def side(v, length):
        if v >= length:
            return (2 * v - length + 1) * length // 2
        return v * (v + 1) // 2 + (length - v)

    def total(v):
        return side(v, index + 1) + side(v, n - index) - v

    lo, hi = 1, maxSum
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if total(mid) <= maxSum:
            lo = mid
        else:
            hi = mid - 1
    return lo
